<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import FieldError from '../../../components/FieldError.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';

interface Choice { id: string; name: string }
interface VariantChoice { id: string; sku: string; name: string | null; product: string }
const props = defineProps<{ statuses: string[]; discountTypes: string[]; scopes: string[]; currencies: string[]; products: Choice[]; categories: Choice[]; variants: VariantChoice[]; targetSearch: string }>();
const form = useForm({ name: '', internal_code: '', description: '', status: 'DRAFT', discount_type: 'PERCENTAGE', discount_value: '', currency: '', starts_at: '', ends_at: '', priority: 0, scope: 'ALL', product_ids: [] as string[], category_ids: [] as string[], variant_ids: [] as string[] });
const targetSearch = ref(props.targetSearch);
const searchTargets = () => router.get('/admin/promotions/create', { target_search: targetSearch.value }, { replace: true });
const submit = () => form.post('/admin/promotions');
</script>

<template>
    <Head title="Create promotion" /><AdminLayout><section><div class="max-w-3xl"><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">Promotion definition</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">Create a promotion.</h1><p class="mt-4 text-sm text-[#637067]">Dates are entered and evaluated in UTC. Base prices remain unchanged.</p></div>
    <form class="mt-8 flex max-w-xl gap-3" @submit.prevent="searchTargets"><input v-model="targetSearch" type="search" placeholder="Find target product, category, or SKU" class="min-w-0 flex-1 border bg-white px-4 py-3" /><button class="border border-[#17211b] px-5 py-3 font-semibold">Find targets</button></form>
    <form class="mt-6 grid gap-8 border border-[#17211b]/15 bg-[#f8f5ed] p-6 sm:p-8" @submit.prevent="submit">
        <div class="grid gap-5 sm:grid-cols-2"><div><label for="name" class="mb-2 block text-sm font-semibold">Name</label><input id="name" v-model="form.name" required maxlength="160" autofocus class="w-full border border-[#17211b]/25 bg-white px-4 py-3" /><FieldError :message="form.errors.name" /></div><div><label for="internal_code" class="mb-2 block text-sm font-semibold">Internal code (optional)</label><input id="internal_code" v-model="form.internal_code" maxlength="60" class="w-full border border-[#17211b]/25 bg-white px-4 py-3 font-mono uppercase" /><FieldError :message="form.errors.internal_code" /></div></div>
        <div><label for="description" class="mb-2 block text-sm font-semibold">Description</label><textarea id="description" v-model="form.description" rows="3" maxlength="10000" class="w-full border border-[#17211b]/25 bg-white px-4 py-3" /><FieldError :message="form.errors.description" /></div>
        <div class="grid gap-5 sm:grid-cols-4"><div><label class="mb-2 block text-sm font-semibold">Status</label><select v-model="form.status" class="w-full border bg-white px-4 py-3"><option v-for="status in props.statuses" :key="status">{{ status }}</option></select><FieldError :message="form.errors.status" /></div><div><label class="mb-2 block text-sm font-semibold">Discount type</label><select v-model="form.discount_type" class="w-full border bg-white px-4 py-3"><option v-for="type in props.discountTypes" :key="type">{{ type }}</option></select><FieldError :message="form.errors.discount_type" /></div><div><label class="mb-2 block text-sm font-semibold">Value</label><input v-model="form.discount_value" required inputmode="decimal" placeholder="0.0000" class="w-full border bg-white px-4 py-3 font-mono" /><FieldError :message="form.errors.discount_value" /></div><div><label class="mb-2 block text-sm font-semibold">Currency</label><select v-model="form.currency" :disabled="form.discount_type !== 'FIXED_AMOUNT'" class="w-full border bg-white px-4 py-3 disabled:bg-stone-100"><option value="">Choose</option><option v-for="currency in props.currencies" :key="currency">{{ currency }}</option></select><FieldError :message="form.errors.currency" /></div></div>
        <div class="grid gap-5 sm:grid-cols-3"><div><label class="mb-2 block text-sm font-semibold">Starts at (UTC)</label><input v-model="form.starts_at" type="datetime-local" class="w-full border bg-white px-4 py-3" /><FieldError :message="form.errors.starts_at" /></div><div><label class="mb-2 block text-sm font-semibold">Ends at (UTC, exclusive)</label><input v-model="form.ends_at" type="datetime-local" class="w-full border bg-white px-4 py-3" /><FieldError :message="form.errors.ends_at" /></div><div><label class="mb-2 block text-sm font-semibold">Priority</label><input v-model.number="form.priority" type="number" min="-1000000" max="1000000" class="w-full border bg-white px-4 py-3 font-mono" /><FieldError :message="form.errors.priority" /></div></div>
        <fieldset><legend class="text-lg font-semibold">Catalog scope</legend><div class="mt-3 flex gap-5"><label v-for="scope in props.scopes" :key="scope" class="flex items-center gap-2"><input v-model="form.scope" type="radio" :value="scope" />{{ scope === 'ALL' ? 'All catalog' : 'Selected targets' }}</label></div><FieldError :message="form.errors.scope" /></fieldset>
        <div v-if="form.scope === 'SELECTED'" class="grid gap-6 lg:grid-cols-3"><fieldset><legend class="mb-3 font-semibold">Products</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="product in props.products" :key="product.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.product_ids" type="checkbox" :value="product.id" />{{ product.name }}</label></div><FieldError :message="form.errors.product_ids" /></fieldset><fieldset><legend class="mb-3 font-semibold">Exact categories</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="category in props.categories" :key="category.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.category_ids" type="checkbox" :value="category.id" />{{ category.name }}</label></div><FieldError :message="form.errors.category_ids" /></fieldset><fieldset><legend class="mb-3 font-semibold">Variants</legend><div class="grid max-h-72 gap-2 overflow-y-auto"><label v-for="variant in props.variants" :key="variant.id" class="flex items-center gap-3 border bg-white p-3"><input v-model="form.variant_ids" type="checkbox" :value="variant.id" /><span>{{ variant.product }}<small class="block font-mono">{{ variant.sku }} / {{ variant.name }}</small></span></label></div><FieldError :message="form.errors.variant_ids" /></fieldset></div>
        <p class="text-xs text-[#637067]">Target selectors show up to 50 records per type. Category matching is exact and does not include descendants.</p>
        <div class="flex gap-4"><button :disabled="form.processing" class="bg-[#17211b] px-5 py-3 text-sm font-semibold text-white disabled:opacity-60">{{ form.processing ? 'Creating...' : 'Create promotion' }}</button><Link href="/admin/promotions" class="py-3 text-sm font-semibold text-emerald-800">Cancel</Link></div>
    </form></section></AdminLayout>
</template>
